insert into public.dilemma_room_questions(id,pack,axis,question) values
('balanced-r01', 'general', 'reason', '{"theme":"ethics","prompt":{"fr":"Une bombe menace 3 000 personnes dans un centre commercial. Dans ce scénario, accuser un innocent garantit leur survie, mais le condamne à la prison à vie. Refuser entraîne la mort des 3 000 personnes. Que choisis-tu ?","en":"A bomb threatens 3,000 people in a shopping mall. In this thought experiment, framing an innocent person guarantees everyone survives, but sends that person to prison for life. Refusing means all 3,000 die. What do you choose?"},"id":"balanced-r01","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Accuser l''innocent pour sauver les 3 000 vies, et porter cette injustice.","en":"Frame the innocent person to save 3,000 lives, and live with that injustice."},"weights":{"reason":3}},{"text":{"fr":"Refuser de condamner un innocent, malgré les 3 000 vies perdues.","en":"Refuse to condemn an innocent person, despite the 3,000 lives lost."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r02', 'general', 'reason', '{"theme":"work","prompt":{"fr":"Une coopérative doit supprimer cinq postes ou fermer dans un mois, laissant cinquante personnes sans emploi. Les cinq concernés sont tes amis. Tu as la décision finale.","en":"A worker-owned business must cut five jobs or close next month, leaving fifty people out of work. The five affected are your friends. The final decision is yours."},"id":"balanced-r02","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Supprimer les cinq postes pour préserver les autres, malgré leur confiance en moi.","en":"Cut the five jobs to protect the others, despite their trust in me."},"weights":{"reason":3}},{"text":{"fr":"Garder tout le monde jusqu''au bout, en partageant le risque de fermeture.","en":"Keep everyone until the end and share the risk of closure."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r03', 'general', 'reason', '{"theme":"relationships","prompt":{"fr":"Ton meilleur ami a triché pour obtenir une bourse dont il a besoin. La révélation rendrait sa place au candidat lésé, mais ton ami abandonnerait ses études.","en":"Your closest friend cheated to win a scholarship they desperately need. Exposing it would restore the rightful winner''s place, but your friend would have to drop out."},"id":"balanced-r03","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Révéler la fraude et rendre la bourse au candidat lésé.","en":"Expose the cheating and return the scholarship to its rightful winner."},"weights":{"reason":3}},{"text":{"fr":"Protéger mon ami en laissant l''autre candidat subir l''injustice.","en":"Protect my friend while letting the other applicant bear the injustice."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r04', 'general', 'reason', '{"theme":"powers","prompt":{"fr":"Tu peux effacer le deuil d''un proche. Il retrouvera la paix, mais perdra aussi tous les souvenirs heureux de la personne disparue. Il t''a confié ce choix.","en":"You can erase a loved one''s grief. They would find peace, but lose every happy memory of the person who died. They have entrusted the choice to you."},"id":"balanced-r04","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Effacer la douleur, même au prix de ces souvenirs.","en":"Remove the pain, even at the cost of those memories."},"weights":{"reason":3}},{"text":{"fr":"Préserver les souvenirs, avec la douleur qui les accompagne.","en":"Preserve the memories, along with the pain they carry."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r05', 'general', 'reason', '{"theme":"travel","prompt":{"fr":"Après une inondation, ton véhicule peut ramener ton frère isolé ou quatre inconnus isolés ailleurs. Un seul trajet est possible avant la fermeture de la route.","en":"After a flood, your vehicle can collect your stranded brother or four strangers stranded elsewhere. There is time for just one trip before the road closes."},"id":"balanced-r05","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Ramener les quatre inconnus et laisser mon frère attendre sans garantie.","en":"Collect the four strangers and leave my brother waiting without guarantees."},"weights":{"reason":3}},{"text":{"fr":"Ramener mon frère et laisser les quatre inconnus attendre sans garantie.","en":"Collect my brother and leave the four strangers waiting without guarantees."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r06', 'general', 'reason', '{"theme":"everyday","prompt":{"fr":"Ton refuge peut soigner un chien auquel toute l''équipe est attachée, ou vacciner cent animaux avec la même somme. Sans soin, le chien ne survivra pas.","en":"Your shelter can treat one dog the whole team loves, or vaccinate a hundred animals with the same money. Without treatment, the dog will not survive."},"id":"balanced-r06","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Financer les cent vaccins et renoncer au traitement du chien.","en":"Fund the hundred vaccinations and forgo the dog''s treatment."},"weights":{"reason":3}},{"text":{"fr":"Soigner le chien et renoncer aux cent vaccinations.","en":"Treat the dog and forgo the hundred vaccinations."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r07', 'general', 'reason', '{"theme":"absurd","prompt":{"fr":"Une machine rend mille inconnus heureux pour un an, mais te retire une amitié précieuse : vous ne vous reconnaîtrez plus. Tu es seul à pouvoir l''activer.","en":"A machine gives a thousand strangers a happy year, but takes away one treasured friendship: you will no longer recognise each other. Only you can switch it on."},"id":"balanced-r07","pack":"general","stableScoring":true,"options":[{"text":{"fr":"L''activer et perdre cette amitié pour leur bonheur.","en":"Switch it on and lose that friendship for their happiness."},"weights":{"reason":3}},{"text":{"fr":"Garder cette amitié et renoncer au bonheur offert aux mille inconnus.","en":"Keep the friendship and give up the happiness offered to a thousand strangers."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r08', 'general', 'reason', '{"theme":"ethics","prompt":{"fr":"Une preuve innocente ton parent d''une accusation. Elle révèle aussi la faute grave d''une personne qui t''a sauvé la vie et qui serait emprisonnée. Tu ne peux pas dissocier les deux.","en":"One piece of evidence clears your parent of an accusation. It also reveals a serious offence by the person who saved your life, who would be imprisoned. The two cannot be separated."},"id":"balanced-r08","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Transmettre la preuve complète, même contre la personne qui m''a sauvé.","en":"Submit the full evidence, even against the person who saved me."},"weights":{"reason":3}},{"text":{"fr":"La retenir par loyauté, en laissant mon parent accusé.","en":"Withhold it out of loyalty, leaving my parent accused."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r09', 'general', 'reason', '{"theme":"relationships","prompt":{"fr":"Un ami te demande un avis sincère sur le projet auquel il a consacré dix ans. Tu sais qu''il échouera ; il doit présenter le projet demain et ne peut plus le modifier.","en":"A friend asks for your honest view of a project they spent ten years on. You know it will fail; they present it tomorrow and can no longer change it."},"id":"balanced-r09","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Dire ce que je pense, quitte à briser son élan avant la présentation.","en":"Tell them what I think, even if it destroys their confidence before the pitch."},"weights":{"reason":3}},{"text":{"fr":"L''encourager pour préserver sa confiance, en lui cachant mon avis.","en":"Encourage them to protect their confidence, while hiding my real opinion."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-r10', 'general', 'reason', '{"theme":"work","prompt":{"fr":"Tu gères un fonds d''urgence. Un dossier anonyme répond mieux aux critères qu''un dossier porté par une famille que tu connais et dont tu vois la détresse. Une seule aide reste.","en":"You manage an emergency fund. An anonymous application meets the criteria better than one from a family you know whose distress you see every day. One grant remains."},"id":"balanced-r10","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Suivre les critères et refuser la famille que je connais.","en":"Follow the criteria and turn down the family I know."},"weights":{"reason":3}},{"text":{"fr":"Aider la famille que je connais et déroger aux critères communs.","en":"Help the family I know and make an exception to the shared criteria."},"weights":{"reason":-3}}]}'::jsonb),
('balanced-a01', 'general', 'adventure', '{"theme":"travel","prompt":{"fr":"En montagne, un membre du groupe manque à l''appel. Partir le chercher t''expose à une tempête ; rester assure ta sécurité mais retarde son secours de plusieurs heures.","en":"A member of your hiking group is missing. Searching exposes you to an incoming storm; staying keeps you safe but delays help for several hours."},"id":"balanced-a01","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Partir chercher la personne en acceptant de me mettre en danger.","en":"Go looking, accepting the danger to myself."},"weights":{"adventure":3}},{"text":{"fr":"Rester à l''abri et attendre les secours, malgré le délai.","en":"Stay sheltered and wait for rescuers, despite the delay."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a02', 'general', 'adventure', '{"theme":"work","prompt":{"fr":"Tu peux témoigner publiquement d''une injustice au travail. Ton témoignage a une chance sur deux de la faire cesser, mais tu perdras certainement ton emploi. Le silence protège ton revenu.","en":"You can speak publicly about an injustice at work. Your testimony has a fifty-fifty chance of ending it, but will certainly cost you your job. Silence protects your income."},"id":"balanced-a02","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Témoigner et perdre mon revenu pour cette chance de changement.","en":"Speak out and lose my income for that chance of change."},"weights":{"adventure":3}},{"text":{"fr":"Garder mon emploi et laisser cette injustice sans mon témoignage.","en":"Keep my job and leave the injustice without my testimony."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a03', 'general', 'adventure', '{"theme":"powers","prompt":{"fr":"Tu peux tester un pouvoir qui guérit une maladie : une chance sur deux de guérir, une chance sur deux d''aggraver ton état. Sans le test, ton état reste stable mais limitant.","en":"You can test a healing power: a fifty-fifty chance of recovery or of getting worse. Without it, your condition stays stable but limiting."},"id":"balanced-a03","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Tenter la guérison en acceptant le risque d''aggravation.","en":"Try for recovery, accepting the risk of getting worse."},"weights":{"adventure":3}},{"text":{"fr":"Garder mon état stable et renoncer à cette chance de guérison.","en":"Keep my stable condition and give up this chance of recovery."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a04', 'general', 'adventure', '{"theme":"relationships","prompt":{"fr":"Avouer tes sentiments pourrait transformer une amitié essentielle en histoire d''amour. L''autre t''a dit qu''un amour non partagé mettrait fin à votre proximité.","en":"Confessing your feelings could turn an essential friendship into a relationship. The other person has said unreturned feelings would end your closeness."},"id":"balanced-a04","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Avouer mes sentiments au risque de perdre notre proximité.","en":"Confess, risking the closeness we already have."},"weights":{"adventure":3}},{"text":{"fr":"Préserver l''amitié et renoncer à savoir si cet amour est partagé.","en":"Protect the friendship and give up knowing whether the feeling is mutual."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a05', 'general', 'adventure', '{"theme":"everyday","prompt":{"fr":"Tu peux placer toutes tes économies dans le commerce d''un ami : il pourrait sauver son emploi et doubler ta mise, mais une faillite vous laisserait tous deux sans réserve.","en":"You can put all your savings into a friend''s shop: it could save their job and double your money, but failure would leave you both without a safety net."},"id":"balanced-a05","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Investir mes économies et partager le risque avec lui.","en":"Invest my savings and share the risk with them."},"weights":{"adventure":3}},{"text":{"fr":"Conserver ma réserve en le laissant chercher une solution incertaine.","en":"Keep my safety net and leave them to seek an uncertain alternative."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a06', 'general', 'adventure', '{"theme":"ethics","prompt":{"fr":"Des documents pourraient disculper un inconnu emprisonné. Les publier révèle aussi ton identité à des personnes qui te menacent. Les garder secrets te protège, mais son recours échoue.","en":"Documents could clear an imprisoned stranger. Publishing them also exposes your identity to people threatening you. Keeping them secret protects you, but their appeal fails."},"id":"balanced-a06","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Publier les documents malgré les menaces contre moi.","en":"Publish the documents despite the threats to me."},"weights":{"adventure":3}},{"text":{"fr":"Me protéger en renonçant à les publier.","en":"Protect myself by withholding them."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a07', 'general', 'adventure', '{"theme":"absurd","prompt":{"fr":"Une porte mène à une société sans faim. Tu peux y emmener dix volontaires, mais personne ne saura revenir. Rester vous laisse dans un village qui manque de nourriture.","en":"A doorway leads to a society without hunger. You can take ten willing volunteers, but nobody knows how to return. Staying leaves you in a village short of food."},"id":"balanced-a07","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Franchir la porte avec eux sans possibilité connue de retour.","en":"Step through with them, with no known way back."},"weights":{"adventure":3}},{"text":{"fr":"Rester dans notre monde malgré les pénuries.","en":"Stay in our world despite the shortages."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a08', 'general', 'adventure', '{"theme":"travel","prompt":{"fr":"Ton bateau reçoit un appel de détresse. Faire le détour épuise votre réserve de carburant et menace votre retour ; continuer abandonne l''autre équipage à une attente incertaine.","en":"Your boat receives a distress call. Diverting uses your fuel reserve and puts your return at risk; continuing leaves the other crew waiting for uncertain help."},"id":"balanced-a08","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Faire le détour au risque de compromettre notre retour.","en":"Divert, risking our own return."},"weights":{"adventure":3}},{"text":{"fr":"Préserver notre carburant et poursuivre notre route.","en":"Keep our fuel reserve and continue on course."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a09', 'general', 'adventure', '{"theme":"work","prompt":{"fr":"Une petite équipe te propose de développer une invention utile mais incertaine. Pour la rejoindre, tu dois quitter un poste stable qui finance l''aide que tu apportes à tes proches.","en":"A small team asks you to develop a useful but uncertain invention. Joining means leaving the stable job that funds your support for loved ones."},"id":"balanced-a09","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Rejoindre le projet en réduisant l''aide garantie à mes proches.","en":"Join the project, reducing the support I can guarantee my loved ones."},"weights":{"adventure":3}},{"text":{"fr":"Garder mon poste et renoncer à participer à cette invention.","en":"Keep my job and give up my role in the invention."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-a10', 'general', 'adventure', '{"theme":"relationships","prompt":{"fr":"Ton partenaire veut reconstruire votre vie à l''étranger. Le suivre pourrait sauver votre couple mais te prive de ton réseau ; rester préserve tes appuis et met fin au couple.","en":"Your partner wants to rebuild your lives abroad. Going could save the relationship but costs you your support network; staying keeps your support and ends the relationship."},"id":"balanced-a10","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Partir et reconstruire mes repères pour tenter de sauver le couple.","en":"Move and rebuild my support system to try to save the relationship."},"weights":{"adventure":3}},{"text":{"fr":"Rester auprès de mes appuis et accepter la séparation.","en":"Stay near my support network and accept the separation."},"weights":{"adventure":-3}}]}'::jsonb),
('balanced-i01', 'general', 'independence', '{"theme":"relationships","prompt":{"fr":"Ta famille attend que tu reprennes son commerce. Refuser lui impose une vente douloureuse ; accepter t''oblige à abandonner le métier que tu as choisi.","en":"Your family expects you to take over their business. Refusing forces a painful sale; accepting means abandoning the career you chose."},"id":"balanced-i01","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Choisir mon métier et laisser ma famille vendre le commerce.","en":"Choose my career and let my family sell the business."},"weights":{"independence":3}},{"text":{"fr":"Reprendre le commerce et renoncer à mon projet professionnel.","en":"Take over the business and give up my career plans."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i02', 'general', 'independence', '{"theme":"work","prompt":{"fr":"Ton équipe veut signer une lettre collective dont tu désapprouves une demande centrale. Ta signature rendrait leur négociation crédible ; ton refus la ferait échouer.","en":"Your team wants to sign a joint letter whose central demand you disagree with. Your signature would make the negotiation credible; refusing would sink it."},"id":"balanced-i02","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Refuser de signer une demande contraire à mes convictions.","en":"Refuse to sign a demand that goes against my beliefs."},"weights":{"independence":3}},{"text":{"fr":"Signer pour soutenir le groupe, malgré mon désaccord.","en":"Sign to support the group, despite my disagreement."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i03', 'general', 'independence', '{"theme":"travel","prompt":{"fr":"Tu as économisé des années pour voyager seul. Ton groupe d''amis ne peut partir que si tu verses ta réserve dans leur caisse commune, ce qui annule ton voyage personnel.","en":"You saved for years to travel solo. Your friends can only take their trip if you put your savings into the shared fund, cancelling your own journey."},"id":"balanced-i03","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Garder mon voyage et laisser le groupe renoncer au sien.","en":"Keep my solo trip and let the group give up theirs."},"weights":{"independence":3}},{"text":{"fr":"Financer le voyage commun et abandonner mon itinéraire.","en":"Fund the shared trip and abandon my own itinerary."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i04', 'general', 'independence', '{"theme":"everyday","prompt":{"fr":"Ta colocation décide de rester ensemble pour éviter une hausse de loyer à chacun. Tu as besoin de vivre seul ; ton départ rendra le logement trop cher pour les autres.","en":"Your housemates agree to stay together to keep rent affordable. You need to live alone; leaving would make the house too expensive for the others."},"id":"balanced-i04","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Partir vivre seul, même si les autres doivent déménager.","en":"Move out on my own, even if the others must move too."},"weights":{"independence":3}},{"text":{"fr":"Rester pour protéger leur logement, malgré mon besoin d''espace.","en":"Stay to protect their housing, despite my need for space."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i05', 'general', 'independence', '{"theme":"ethics","prompt":{"fr":"Une communauté t''accueille à condition que tu caches durablement une part essentielle de ton identité. La quitter préserve ta liberté mais te laisse sans aucun soutien.","en":"A community will welcome you only if you permanently hide an essential part of who you are. Leaving preserves your freedom but leaves you without support."},"id":"balanced-i05","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Partir pour vivre ouvertement, même sans soutien.","en":"Leave to live openly, even without support."},"weights":{"independence":3}},{"text":{"fr":"Rester et cacher cette part de moi pour garder des liens.","en":"Stay and hide that part of myself to keep those connections."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i06', 'general', 'independence', '{"theme":"powers","prompt":{"fr":"Un pouvoir permet à ton groupe de partager pensées et émotions, ce qui élimine ses malentendus. L''activer supprime aussi toute intimité mentale, pour toi comme pour eux. Tous te laissent trancher.","en":"A power lets your group share thoughts and feelings, ending misunderstandings. Activating it also removes everyone''s mental privacy. They all leave the decision to you."},"id":"balanced-i06","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Préserver nos pensées privées, en gardant nos incompréhensions.","en":"Preserve our private thoughts, keeping our misunderstandings."},"weights":{"independence":3}},{"text":{"fr":"Partager nos pensées pour nous comprendre, sans jardin secret.","en":"Share our thoughts to understand each other, with no private inner world."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i07', 'general', 'independence', '{"theme":"absurd","prompt":{"fr":"Sur une île, chacun doit porter un masque qui rend le groupe uni et paisible. Le tien efface ta personnalité tant que tu le portes. L''enlever te condamne à vivre à l''écart.","en":"On an island, everyone wears a mask that keeps the community united and peaceful. Yours erases your personality while you wear it. Removing it means living apart."},"id":"balanced-i07","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Enlever le masque et vivre à l''écart en restant moi-même.","en":"Remove the mask and live apart while remaining myself."},"weights":{"independence":3}},{"text":{"fr":"Porter le masque et appartenir au groupe en perdant ma singularité.","en":"Wear the mask and belong, at the cost of my individuality."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i08', 'general', 'independence', '{"theme":"relationships","prompt":{"fr":"Un ami traverse une longue période difficile et veut que tu sois joignable chaque nuit. Accepter l''aide beaucoup mais épuise ta vie personnelle ; poser une limite lui donne le sentiment d''être abandonné.","en":"A friend in a prolonged rough patch wants you available every night. Agreeing helps them but drains your personal life; setting a boundary makes them feel abandoned."},"id":"balanced-i08","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Poser une limite, même s''il se sent abandonné.","en":"Set a boundary, even if they feel abandoned."},"weights":{"independence":3}},{"text":{"fr":"Rester disponible chaque nuit au prix de mon équilibre.","en":"Stay available every night at the cost of my own balance."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i09', 'general', 'independence', '{"theme":"work","prompt":{"fr":"Une œuvre collective reçoit une offre à condition d''effacer ta contribution la plus personnelle. Ton refus annule le contrat de toute l''équipe ; accepter dénature ce que tu voulais dire.","en":"A collaborative artwork gets an offer on condition that your most personal contribution is removed. Refusing cancels the team''s contract; accepting distorts your message."},"id":"balanced-i09","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Refuser l''effacement de ma contribution, quitte à perdre le contrat commun.","en":"Refuse to erase my contribution, even if we lose the shared contract."},"weights":{"independence":3}},{"text":{"fr":"Accepter pour que l''équipe obtienne le contrat.","en":"Accept so the team can secure the contract."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-i10', 'general', 'independence', '{"theme":"everyday","prompt":{"fr":"Tes voisins veulent un fonds commun obligatoire pour les coups durs. Tu y perdrais la liberté d''utiliser tes économies, mais ton refus empêche le fonds d''exister.","en":"Your neighbours want a compulsory shared emergency fund. You would lose control over your savings, but your refusal would stop the fund from existing."},"id":"balanced-i10","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Garder la maîtrise de mes économies et renoncer au filet commun.","en":"Keep control of my savings and forgo the shared safety net."},"weights":{"independence":3}},{"text":{"fr":"Mettre mes économies en commun, sans décider seul de leur usage.","en":"Pool my savings without sole control over how they are used."},"weights":{"independence":-3}}]}'::jsonb),
('balanced-f01', 'general', 'future', '{"theme":"relationships","prompt":{"fr":"Une formation de deux ans garantirait une vie plus stable à ta famille. Elle t''éloignerait pendant les dernières années lucides d''un parent malade. Tu ne peux pas la reporter.","en":"A two-year training course would secure a more stable future for your family. It would take you away during an ill parent''s last lucid years. You cannot defer it."},"id":"balanced-f01","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Suivre la formation pour notre avenir, en perdant ce temps ensemble.","en":"Take the course for our future, losing that time together."},"weights":{"future":3}},{"text":{"fr":"Rester auprès de mon parent et renoncer à cette stabilité future.","en":"Stay with my parent and give up that future stability."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f02', 'general', 'future', '{"theme":"everyday","prompt":{"fr":"Une somme inattendue peut payer le dernier voyage dont rêve ta famille réunie, ou constituer une réserve qui évitera probablement de grosses difficultés dans cinq ans.","en":"An unexpected windfall can fund the last trip your whole family dreams of taking together, or build a reserve likely to prevent serious hardship in five years."},"id":"balanced-f02","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Mettre la somme de côté et renoncer à ce voyage ensemble.","en":"Save the money and forgo that trip together."},"weights":{"future":3}},{"text":{"fr":"Faire ce voyage unique et accepter l''incertitude financière future.","en":"Take the once-in-a-lifetime trip and accept future financial uncertainty."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f03', 'general', 'future', '{"theme":"ethics","prompt":{"fr":"Un village peut consommer ses dernières semences pour ne pas avoir faim cet hiver, ou les planter pour une récolte abondante. Les planter impose des mois de rationnement sévère.","en":"A village can eat its remaining seeds to avoid hunger this winter, or plant them for a plentiful harvest. Planting means months of severe rationing."},"id":"balanced-f03","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Planter les semences et imposer le rationnement maintenant.","en":"Plant the seeds and impose rationing now."},"weights":{"future":3}},{"text":{"fr":"Nourrir le village maintenant, sans réserve pour la récolte suivante.","en":"Feed the village now, without reserves for the next harvest."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f04', 'general', 'future', '{"theme":"work","prompt":{"fr":"Ton association peut aider vingt personnes immédiatement ou financer un outil qui en aidera deux cents l''an prochain. Les vingt personnes ne peuvent pas attendre son arrivée.","en":"Your charity can help twenty people immediately or fund a tool that will help two hundred next year. The twenty cannot wait for it."},"id":"balanced-f04","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Financer l''outil pour les deux cents futurs bénéficiaires.","en":"Fund the tool for two hundred future beneficiaries."},"weights":{"future":3}},{"text":{"fr":"Aider les vingt personnes aujourd''hui et renoncer à l''outil.","en":"Help the twenty people today and forgo the tool."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f05', 'general', 'future', '{"theme":"powers","prompt":{"fr":"Tu peux donner dix années heureuses à ton futur toi, mais les payer par une année présente sans joie. Refuser te laisse vivre normalement, sans ces dix années garanties.","en":"You can give your future self ten happy years, paid for with one joyless year now. Refusing lets life carry on normally, without those ten guaranteed years."},"id":"balanced-f05","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Traverser l''année sans joie pour les dix années futures.","en":"Endure the joyless year for ten happy years later."},"weights":{"future":3}},{"text":{"fr":"Préserver cette année de vie et renoncer à la garantie future.","en":"Preserve this year of life and give up the future guarantee."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f06', 'general', 'future', '{"theme":"travel","prompt":{"fr":"Ton unique congé peut servir à revoir un ami qui déménage loin, ou à préparer une reconversion qui ne sera plus accessible ensuite. Aucun autre créneau n''est possible.","en":"Your only time off can be spent seeing a friend before they move far away, or preparing for a career change whose window will then close. There is no other time."},"id":"balanced-f06","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Préparer la reconversion et manquer ces derniers jours ensemble.","en":"Prepare for the career change and miss those last days together."},"weights":{"future":3}},{"text":{"fr":"Revoir mon ami et laisser passer la reconversion.","en":"See my friend and let the career-change opportunity pass."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f07', 'general', 'future', '{"theme":"absurd","prompt":{"fr":"Une horloge te permet de stocker chaque dimanche pour gagner des années de vie après 70 ans. Pendant vingt ans, tu travaillerais donc sans dimanche, tandis que tes proches en profiteraient sans toi.","en":"A clock lets you bank every Sunday for extra years after age seventy. For twenty years you would work through Sundays while your loved ones enjoy them without you."},"id":"balanced-f07","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Stocker les dimanches pour vivre plus longtemps ensuite.","en":"Bank the Sundays to live longer later."},"weights":{"future":3}},{"text":{"fr":"Vivre mes dimanches avec mes proches, sans années supplémentaires.","en":"Spend my Sundays with loved ones, without the extra years."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f08', 'general', 'future', '{"theme":"relationships","prompt":{"fr":"Ton couple peut retrouver une stabilité durable grâce à une année de séparation convenue. Rester ensemble évite la douleur immédiate mais laisse le conflit intact, sans autre solution disponible.","en":"Your relationship can regain lasting stability through an agreed year apart. Staying together avoids immediate pain but leaves the conflict unresolved, with no other option available."},"id":"balanced-f08","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Accepter l''année de séparation pour reconstruire ensuite.","en":"Accept the year apart to rebuild afterwards."},"weights":{"future":3}},{"text":{"fr":"Rester ensemble maintenant, même avec ce conflit persistant.","en":"Stay together now, even with the continuing conflict."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f09', 'general', 'future', '{"theme":"everyday","prompt":{"fr":"Un jardin partagé doit choisir entre couper ses arbres malades pour en planter de nouveaux, ou préserver dix ans d''ombre avant leur disparition définitive. Le budget ne permet qu''une intervention.","en":"A community garden must choose between cutting down diseased trees to plant new ones, or keeping ten more years of shade before they die. The budget covers one intervention only."},"id":"balanced-f09","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Replanter maintenant et priver le quartier d''ombre plusieurs années.","en":"Replant now and leave the neighbourhood without shade for years."},"weights":{"future":3}},{"text":{"fr":"Garder l''ombre actuelle et renoncer au renouvellement financé.","en":"Keep today''s shade and give up the funded renewal."},"weights":{"future":-3}}]}'::jsonb),
('balanced-f10', 'general', 'future', '{"theme":"work","prompt":{"fr":"Tu peux utiliser ton budget pour augmenter les salaires cette année ou pour financer une formation qui sécurisera les emplois à long terme. L''équipe vit difficilement avec ses revenus actuels.","en":"You can spend your budget on raises this year or training that will secure jobs long-term. The team is struggling on its current pay."},"id":"balanced-f10","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Financer la formation, en laissant les difficultés de revenu durer.","en":"Fund the training, leaving the current pay hardship unresolved."},"weights":{"future":3}},{"text":{"fr":"Augmenter les salaires et renoncer à la formation protectrice.","en":"Raise salaries and forgo the training that would protect jobs."},"weights":{"future":-3}}]}'::jsonb),
('balanced-s01', 'general', 'structure', '{"theme":"ethics","prompt":{"fr":"Tu gères une file d''attente pour un logement. Une famille arrivée en dernier est en grande difficulté, mais passer devant ferait attendre une autre famille qui respecte les règles depuis un an.","en":"You manage a housing waiting list. A newly arrived family is in serious difficulty, but moving them ahead would delay another family that has followed the rules for a year."},"id":"balanced-s01","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Respecter l''ordre de la file, malgré l''urgence nouvelle.","en":"Respect the waiting list, despite the new emergency."},"weights":{"structure":3}},{"text":{"fr":"Créer une exception pour la nouvelle famille, au détriment de l''autre.","en":"Make an exception for the new family at the other''s expense."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s02', 'general', 'structure', '{"theme":"work","prompt":{"fr":"Une collègue a raté une date limite pour une raison personnelle légitime. Accepter son dossier oblige à refuser celui d''une personne qui a respecté toutes les consignes.","en":"A colleague missed a deadline for a legitimate personal reason. Accepting her application means rejecting someone who followed every instruction."},"id":"balanced-s02","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Maintenir la date limite et refuser le dossier tardif.","en":"Enforce the deadline and reject the late application."},"weights":{"structure":3}},{"text":{"fr":"Adapter la règle à sa situation et écarter le dossier ponctuel.","en":"Adapt the rule to her circumstances and reject the on-time application."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s03', 'general', 'structure', '{"theme":"travel","prompt":{"fr":"Une expédition suit un plan sûr mais abandonnera son objectif à cause d''un retard. Une route improvisée pourrait permettre de réussir, sans aucune information fiable sur son état.","en":"An expedition''s safe plan will miss its goal because of a delay. An improvised route could still get you there, with no reliable information about its condition."},"id":"balanced-s03","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Suivre le plan sûr et renoncer à l''objectif.","en":"Follow the safe plan and give up the goal."},"weights":{"structure":3}},{"text":{"fr":"Improviser la route pour tenter de réussir, sans garanties.","en":"Improvise the route to try to succeed, without guarantees."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s04', 'general', 'structure', '{"theme":"powers","prompt":{"fr":"Une ville te propose de choisir son système de transports : un réseau parfaitement fiable mais figé pour trente ans, ou un réseau adaptable où les trajets sont souvent imprévisibles.","en":"A city asks you to choose its transport system: a perfectly reliable network fixed for thirty years, or an adaptable one with often unpredictable journeys."},"id":"balanced-s04","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Garantir la fiabilité, même si les besoins changent ensuite.","en":"Guarantee reliability, even if needs change later."},"weights":{"structure":3}},{"text":{"fr":"Préserver l''adaptation, malgré l''incertitude des trajets quotidiens.","en":"Preserve adaptability, despite uncertain daily journeys."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s05', 'general', 'structure', '{"theme":"relationships","prompt":{"fr":"Un accord entre frères et sœurs répartit à parts égales un héritage. Le modifier permettrait à l''un de réaliser un projet unique, mais briserait la promesse faite aux autres.","en":"A sibling agreement splits an inheritance equally. Changing it would let one sibling pursue a unique project, but break the promise made to the others."},"id":"balanced-s05","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Tenir l''accord égalitaire et laisser passer son projet.","en":"Keep the equal split and let the project go."},"weights":{"structure":3}},{"text":{"fr":"Réinventer le partage pour son projet, en rompant l''accord.","en":"Redesign the split for the project, breaking the agreement."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s06', 'general', 'structure', '{"theme":"everyday","prompt":{"fr":"Pour accueillir des voisins sans logement, tu peux suivre une procédure qui prendra un mois, ou improviser un hébergement collectif dès ce soir sans règles communes, avec un risque de conflits.","en":"To house displaced neighbours, you can follow a process taking a month, or arrange shared accommodation tonight without agreed rules, risking conflict."},"id":"balanced-s06","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Attendre le cadre organisé, en laissant un mois d''incertitude.","en":"Wait for an organised framework, leaving a month of uncertainty."},"weights":{"structure":3}},{"text":{"fr":"Improviser l''accueil immédiat, malgré les conflits possibles.","en":"Improvise immediate shelter, despite possible conflicts."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s07', 'general', 'structure', '{"theme":"absurd","prompt":{"fr":"Un théâtre magique peut rejouer chaque soir un spectacle parfait et identique, ou inventer une œuvre nouvelle parfois sublime, parfois ratée. Les recettes financent un refuge.","en":"A magical theatre can repeat a perfect show every night, or invent a new one that may be brilliant or a disaster. Ticket sales fund a shelter."},"id":"balanced-s07","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Choisir le spectacle reproductible pour stabiliser les recettes.","en":"Choose the repeatable show to stabilise income."},"weights":{"structure":3}},{"text":{"fr":"Choisir la création nouvelle en acceptant des recettes incertaines.","en":"Choose new creations and accept uncertain income."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s08', 'general', 'structure', '{"theme":"work","prompt":{"fr":"Une invention peut être livrée sous une forme éprouvée mais inaccessible à certains utilisateurs, ou repensée sans validation complète pour inclure tout le monde. Le financement s''arrête demain.","en":"An invention can ship in a tested form that excludes some users, or be redesigned without full validation to include everyone. Funding ends tomorrow."},"id":"balanced-s08","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Livrer la forme éprouvée, malgré les personnes exclues.","en":"Ship the tested version, despite the people it excludes."},"weights":{"structure":3}},{"text":{"fr":"Livrer la version repensée, malgré ses incertitudes.","en":"Ship the redesigned version, despite its uncertainties."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s09', 'general', 'structure', '{"theme":"ethics","prompt":{"fr":"Un concours promet l''anonymat pour juger uniquement les œuvres. Connaître les parcours permettrait de soutenir des talents moins favorisés, mais changerait la règle après les candidatures.","en":"A competition promises anonymous judging based only on the work. Learning the entrants'' backgrounds could support less privileged talent, but changes the rule after entries close."},"id":"balanced-s09","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Garder le jugement anonyme promis, sans corriger les écarts de départ.","en":"Keep the promised anonymous judging, without correcting unequal starting points."},"weights":{"structure":3}},{"text":{"fr":"Prendre les parcours en compte, en changeant la règle annoncée.","en":"Consider people''s backgrounds, changing the announced rule."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-s10', 'general', 'structure', '{"theme":"relationships","prompt":{"fr":"Un ami te confie une fête importante avec un programme précis. Un imprévu permettrait une célébration plus personnelle, mais seulement en abandonnant ce qu''il t''a demandé.","en":"A friend entrusts you with an important celebration and an exact plan. An unexpected opportunity could make it more personal, but only by abandoning their instructions."},"id":"balanced-s10","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Respecter le programme confié et laisser passer l''occasion.","en":"Honour the agreed plan and let the opportunity pass."},"weights":{"structure":3}},{"text":{"fr":"Réinventer la fête, au risque de trahir ses attentes.","en":"Reinvent the celebration, risking a betrayal of their expectations."},"weights":{"structure":-3}}]}'::jsonb),
('balanced-m01', 'general', 'ambition', '{"theme":"work","prompt":{"fr":"Ton travail a sauvé un projet, mais tout le mérite est attribué à ton responsable. Rétablir les faits t''ouvrirait une promotion et lui ferait perdre son poste ; te taire le protège.","en":"Your work saved a project, but your manager gets all the credit. Setting the record straight would earn you a promotion and cost them their role; silence protects them."},"id":"balanced-m01","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Revendiquer ma contribution et accepter sa perte de poste.","en":"Claim my contribution and accept that they lose their role."},"weights":{"ambition":3}},{"text":{"fr":"Laisser le mérite à mon responsable et renoncer à ma promotion.","en":"Let my manager keep the credit and give up my promotion."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m02', 'general', 'ambition', '{"theme":"relationships","prompt":{"fr":"Tu as écrit anonymement un texte qui a rendu un ami célèbre, avec son accord. On t''offre enfin de reconnaître ton rôle, mais cela ruinerait sa réputation. Le secret était ta promesse.","en":"You anonymously wrote a piece that made a friend famous, with their agreement. You can finally receive credit, but it would ruin their reputation. Secrecy was your promise."},"id":"balanced-m02","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Révéler mon rôle pour être reconnu, en rompant ma promesse.","en":"Reveal my role to receive recognition, breaking my promise."},"weights":{"ambition":3}},{"text":{"fr":"Tenir ma promesse et laisser mon travail porter son nom.","en":"Keep my promise and leave my work under their name."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m03', 'general', 'ambition', '{"theme":"ethics","prompt":{"fr":"Tu peux diriger une organisation utile, mais seulement en écartant la personne qui t''a formé et qui tient à son poste. Rester à ses côtés limite ton influence, mais respecte votre lien.","en":"You can lead an organisation doing good work, but only by replacing the mentor who wants to stay in charge. Staying beside them limits your influence but honours your bond."},"id":"balanced-m03","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Prendre la direction en écartant mon mentor.","en":"Take the leadership role by replacing my mentor."},"weights":{"ambition":3}},{"text":{"fr":"Rester à ses côtés et renoncer à diriger.","en":"Stay beside them and give up the leadership role."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m04', 'general', 'ambition', '{"theme":"travel","prompt":{"fr":"Une expédition propose de donner ton nom à sa découverte. Accepter efface celui d''un collaborateur moins connu ; refuser rend la découverte anonyme pour vous deux.","en":"An expedition offers to name its discovery after you. Accepting leaves out a lesser-known collaborator; refusing makes the discovery anonymous for both of you."},"id":"balanced-m04","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Accepter que mon nom reste, même sans celui de mon collaborateur.","en":"Accept having my name remembered, even without my collaborator''s."},"weights":{"ambition":3}},{"text":{"fr":"Choisir l''anonymat pour ne pas m''approprier notre découverte.","en":"Choose anonymity rather than claim our shared discovery."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m05', 'general', 'ambition', '{"theme":"everyday","prompt":{"fr":"Un prix local récompense ton bénévolat. Accepter apporte une reconnaissance méritée, mais détourne l''attention d''un collectif discret ; refuser lui rend la scène sans mentionner ton rôle.","en":"A local award recognises your volunteering. Accepting gives you deserved credit but takes attention from a quiet collective; declining gives them the spotlight without mentioning you."},"id":"balanced-m05","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Accepter le prix et prendre ma place dans la lumière.","en":"Accept the award and take my place in the spotlight."},"weights":{"ambition":3}},{"text":{"fr":"Céder la scène au collectif et rester sans reconnaissance publique.","en":"Give the collective the stage and remain publicly unrecognised."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m06', 'general', 'ambition', '{"theme":"powers","prompt":{"fr":"Tu peux accomplir une œuvre qui changera le monde, mais tous ceux qui t''aiment t''oublieront. Ou accomplir une œuvre modeste, entouré des tiens, sans laisser de nom dans l''histoire.","en":"You can create something that changes the world, but everyone who loves you will forget you. Or do modest work surrounded by loved ones, leaving no name in history."},"id":"balanced-m06","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Choisir l''œuvre immense et perdre ma place auprès des miens.","en":"Choose the world-changing work and lose my place among loved ones."},"weights":{"ambition":3}},{"text":{"fr":"Choisir la vie entourée et renoncer à cette trace immense.","en":"Choose life with loved ones and give up that vast legacy."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m07', 'general', 'ambition', '{"theme":"absurd","prompt":{"fr":"Un génie garantit que ton nom restera célèbre mille ans, mais chacun se souviendra aussi de ta pire erreur. Refuser efface toute trace publique de toi après ta mort.","en":"A genie guarantees your name will be famous for a thousand years, but everyone will also remember your worst mistake. Refusing erases all public trace of you after death."},"id":"balanced-m07","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Accepter la célébrité avec le souvenir éternel de mon erreur.","en":"Accept fame with the permanent memory of my mistake."},"weights":{"ambition":3}},{"text":{"fr":"Accepter l''oubli public pour ne pas exposer cette erreur.","en":"Accept public oblivion rather than expose that mistake."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m08', 'general', 'ambition', '{"theme":"work","prompt":{"fr":"Une promotion te permettrait enfin de décider, mais t''oblige à superviser et évaluer tes amis. La refuser préserve vos rapports d''égal à égal et ferme cette voie pour longtemps.","en":"A promotion would finally give you decision-making power, but requires you to supervise and assess your friends. Declining preserves your equal footing and closes that path for years."},"id":"balanced-m08","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Accepter le pouvoir de décision et le changement de nos relations.","en":"Accept the decision-making power and the change in our relationships."},"weights":{"ambition":3}},{"text":{"fr":"Rester leur égal et renoncer à la promotion.","en":"Remain their peer and give up the promotion."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m09', 'general', 'ambition', '{"theme":"relationships","prompt":{"fr":"Ton partenaire et toi êtes finalistes d''un concours décisif. Tu peux présenter ton meilleur travail, qui le dépassera certainement, ou une œuvre moindre pour lui laisser sa seule chance.","en":"You and your partner are finalists in a life-changing competition. You can submit your best work, which will certainly beat theirs, or a weaker piece to leave them their only chance."},"id":"balanced-m09","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Présenter mon meilleur travail, même si mon partenaire perd.","en":"Submit my best work, even if my partner loses."},"weights":{"ambition":3}},{"text":{"fr":"Présenter une œuvre moindre et lui laisser cette chance.","en":"Submit a weaker piece and leave them that chance."},"weights":{"ambition":-3}}]}'::jsonb),
('balanced-m10', 'general', 'ambition', '{"theme":"ethics","prompt":{"fr":"Tu peux signer de ton nom une aide majeure, ce qui attirera aussi des soutiens pour tes projets. Les bénéficiaires préfèrent la discrétion ; agir anonymement respecte ce souhait mais te ferme ces portes.","en":"You can put your name on a major act of support, attracting backing for your own projects too. The recipients prefer discretion; anonymity honours their wish but closes those doors for you."},"id":"balanced-m10","pack":"general","stableScoring":true,"options":[{"text":{"fr":"Signer l''aide pour développer mon influence, malgré leur préférence.","en":"Put my name on the support to grow my influence, despite their preference."},"weights":{"ambition":3}},{"text":{"fr":"Agir anonymement et renoncer aux portes que cela m''ouvrirait.","en":"Act anonymously and give up the doors it could open for me."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-friendship-01', 'friendship', 'adventure', '{"id":"pack-friendship-01","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami veut investir avec toi vos économies dans son café. Vous pouvez tout perdre ; refuser met fin à son projet. Que fais-tu ?","en":"Your friend wants you both to invest your savings in their café. You could lose everything; refusing ends their project. What do you do?"},"options":[{"text":{"fr":"Investir avec lui malgré le risque de tout perdre.","en":"Invest together despite the risk of losing everything."},"weights":{"adventure":3}},{"text":{"fr":"Garder mes économies et le voir renoncer au café.","en":"Keep my savings and watch them abandon the café."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-friendship-02', 'friendship', 'adventure', '{"id":"pack-friendship-02","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton meilleur ami part un an à vélo. Il te propose de quitter ton emploi pour le suivre, sans garantie de travail au retour.","en":"Your best friend is leaving on a year-long cycling trip. Joining means quitting your job, with no work guaranteed on return."},"options":[{"text":{"fr":"Partir ensemble et accepter l’incertitude du retour.","en":"Go together and accept an uncertain return."},"weights":{"adventure":3}},{"text":{"fr":"Garder mon emploi et manquer cette année ensemble.","en":"Keep my job and miss that year together."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-friendship-03', 'friendship', 'adventure', '{"id":"pack-friendship-03","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un ami monte sur scène pour la première fois. Son partenaire se désiste : tu peux le remplacer sans répétition, devant tes collègues.","en":"A friend is performing on stage for the first time. Their partner cancels: you can fill in without rehearsing, in front of your colleagues."},"options":[{"text":{"fr":"Monter avec lui au risque de me ridiculiser.","en":"Join them on stage and risk embarrassing myself."},"weights":{"adventure":3}},{"text":{"fr":"Refuser et le laisser annuler sa première scène.","en":"Refuse and let them cancel their first performance."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-friendship-04', 'friendship', 'adventure', '{"id":"pack-friendship-04","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton amie veut témoigner publiquement d’une injustice. La soutenir à visage découvert peut vous coûter votre emploi ; elle refuse de parler seule.","en":"Your friend wants to speak publicly about an injustice. Standing beside her could cost both your jobs; she refuses to speak alone."},"options":[{"text":{"fr":"Témoigner avec elle malgré le risque professionnel.","en":"Speak alongside her despite the career risk."},"weights":{"adventure":3}},{"text":{"fr":"Préserver mon emploi et renoncer au témoignage commun.","en":"Protect my job and give up the joint testimony."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-friendship-05', 'friendship', 'adventure', '{"id":"pack-friendship-05","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un ami en reconversion te propose une colocation dans une nouvelle ville. Tu y gagnes sa présence mais perds ton logement stable et ton réseau.","en":"A friend changing careers suggests sharing a home in a new city. You gain their company but lose stable housing and your support network."},"options":[{"text":{"fr":"Déménager avec lui et reconstruire mes repères.","en":"Move with them and rebuild my support network."},"weights":{"adventure":3}},{"text":{"fr":"Rester et accepter que notre quotidien se sépare.","en":"Stay and accept our everyday lives growing apart."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-friendship-06', 'friendship', 'reason', '{"id":"pack-friendship-06","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami a triché pour gagner une bourse. Dire la vérité rend la place au candidat lésé, mais oblige ton ami à arrêter ses études.","en":"Your friend cheated to win a scholarship. Telling the truth restores the rightful winner''s place but forces your friend to leave university."},"options":[{"text":{"fr":"Révéler la fraude malgré les conséquences pour lui.","en":"Expose the cheating despite the consequences for them."},"weights":{"reason":3}},{"text":{"fr":"Protéger mon ami et laisser l’injustice en place.","en":"Protect my friend and let the injustice stand."},"weights":{"reason":-3}}]}'::jsonb),
('pack-friendship-07', 'friendship', 'reason', '{"id":"pack-friendship-07","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Votre association ne peut payer que trois salariés sur quatre. Ton ami est le moins qualifié ; le garder oblige à licencier quelqu’un de plus compétent.","en":"Your association can afford only three of four employees. Your friend is the least qualified; keeping them means firing someone more capable."},"options":[{"text":{"fr":"Choisir selon les compétences, même contre mon ami.","en":"Choose by ability, even at my friend''s expense."},"weights":{"reason":3}},{"text":{"fr":"Garder mon ami malgré le coût pour l’équipe.","en":"Keep my friend despite the cost to the team."},"weights":{"reason":-3}}]}'::jsonb),
('pack-friendship-08', 'friendship', 'reason', '{"id":"pack-friendship-08","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton amie te demande un avis honnête sur son spectacle juste avant une audition. Tu le trouves raté : la vérité pourrait l’aider mais briser sa confiance.","en":"Your friend asks for an honest opinion of her show before an audition. You think it fails: the truth might help but shatter her confidence."},"options":[{"text":{"fr":"Dire ce qui ne fonctionne pas, même si elle perd confiance.","en":"Explain what fails, even if it undermines her confidence."},"weights":{"reason":3}},{"text":{"fr":"L’encourager et taire mes critiques pour la protéger.","en":"Encourage her and hide my criticism to protect her."},"weights":{"reason":-3}}]}'::jsonb),
('pack-friendship-09', 'friendship', 'reason', '{"id":"pack-friendship-09","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu n’as qu’un billet pour un événement important. Ton ami le réclame depuis longtemps, mais un inconnu en a besoin pour retrouver un parent mourant.","en":"You have one ticket for an important journey. Your friend has long counted on it, but a stranger needs it to reach a dying parent."},"options":[{"text":{"fr":"Donner le billet à l’inconnu malgré ma promesse.","en":"Give the stranger the ticket despite my promise."},"weights":{"reason":3}},{"text":{"fr":"Tenir ma promesse à mon ami malgré l’urgence de l’autre.","en":"Keep my promise to my friend despite the other''s emergency."},"weights":{"reason":-3}}]}'::jsonb),
('pack-friendship-10', 'friendship', 'reason', '{"id":"pack-friendship-10","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton meilleur ami est responsable d’un accident matériel. Il te demande de mentir ; sinon il perd son assurance et devra vendre son appartement.","en":"Your best friend caused an accident involving property damage. They ask you to lie; otherwise they lose coverage and must sell their flat."},"options":[{"text":{"fr":"Raconter les faits malgré sa perte financière.","en":"Tell what happened despite their financial loss."},"weights":{"reason":3}},{"text":{"fr":"Mentir pour éviter qu’il perde son appartement.","en":"Lie to prevent them losing their flat."},"weights":{"reason":-3}}]}'::jsonb),
('pack-friendship-11', 'friendship', 'independence', '{"id":"pack-friendship-11","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tes amis n’acceptent ton nouveau partenaire dans le groupe qu’à condition que tu arrêtes de parler d’un sujet qui compte beaucoup pour toi.","en":"Your friends will accept your new partner into the group only if you stop discussing a subject that matters deeply to you."},"options":[{"text":{"fr":"Refuser cette condition, quitte à perdre le groupe.","en":"Reject the condition, even if I lose the group."},"weights":{"independence":3}},{"text":{"fr":"Accepter cette limite pour préserver nos liens.","en":"Accept the limit to preserve our friendships."},"weights":{"independence":-3}}]}'::jsonb),
('pack-friendship-12', 'friendship', 'independence', '{"id":"pack-friendship-12","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami veut ta localisation en permanence pour être rassuré après un accident. Refuser lui donne le sentiment que tu l’abandonnes.","en":"After an accident, your friend wants your live location at all times for reassurance. Refusing makes them feel abandoned."},"options":[{"text":{"fr":"Garder ma vie privée malgré sa déception.","en":"Keep my privacy despite their disappointment."},"weights":{"independence":3}},{"text":{"fr":"Partager ma localisation pour le rassurer.","en":"Share my location to reassure them."},"weights":{"independence":-3}}]}'::jsonb),
('pack-friendship-13', 'friendship', 'independence', '{"id":"pack-friendship-13","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Le groupe a choisi des vacances trop chères pour toi. Tu pourrais suivre en t’endettant, ou partir seul et manquer les souvenirs communs.","en":"Your group chose a holiday you cannot afford. You could go into debt to join, or travel alone and miss the shared memories."},"options":[{"text":{"fr":"Choisir mon propre voyage et manquer le séjour commun.","en":"Choose my own trip and miss the shared holiday."},"weights":{"independence":3}},{"text":{"fr":"M’endetter pour vivre ce séjour avec mes amis.","en":"Take on debt to share this trip with my friends."},"weights":{"independence":-3}}]}'::jsonb),
('pack-friendship-14', 'friendship', 'independence', '{"id":"pack-friendship-14","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami veut vivre chez toi six mois gratuitement. Tu peux l’aider, mais tu devras renoncer à ton intimité et à ton projet d’atelier personnel.","en":"Your friend wants to stay with you rent-free for six months. You can help, but must give up your privacy and planned personal studio."},"options":[{"text":{"fr":"Refuser l’hébergement pour préserver mon espace.","en":"Decline the stay to preserve my own space."},"weights":{"independence":3}},{"text":{"fr":"L’accueillir et mettre mes besoins entre parenthèses.","en":"Take them in and put my own needs on hold."},"weights":{"independence":-3}}]}'::jsonb),
('pack-friendship-15', 'friendship', 'independence', '{"id":"pack-friendship-15","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tes amis te demandent de voter comme eux dans votre collectif. Ton choix personnel est opposé ; le maintenir risque de casser le groupe.","en":"Your friends ask you to vote with them in your shared project. You disagree; standing by your choice could split the group."},"options":[{"text":{"fr":"Voter selon ma conviction malgré la rupture possible.","en":"Vote according to my convictions despite a possible split."},"weights":{"independence":3}},{"text":{"fr":"Suivre le groupe pour préserver notre unité.","en":"Follow the group to preserve our unity."},"weights":{"independence":-3}}]}'::jsonb),
('pack-friendship-16', 'friendship', 'future', '{"id":"pack-friendship-16","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami t’invite à sa dernière soirée avant un départ définitif. Le lendemain, un examen décisif exige une nuit de préparation.","en":"Your friend invites you to their last evening before moving away for good. A decisive exam the next day requires a night of preparation."},"options":[{"text":{"fr":"Préparer l’examen et manquer ses adieux.","en":"Prepare for the exam and miss the goodbye."},"weights":{"future":3}},{"text":{"fr":"Partager ses adieux au risque de rater l’examen.","en":"Share the goodbye and risk failing the exam."},"weights":{"future":-3}}]}'::jsonb),
('pack-friendship-17', 'friendship', 'future', '{"id":"pack-friendship-17","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu peux prêter ton épargne à ton ami pour son mariage ou la garder pour votre projet professionnel commun prévu dans deux ans.","en":"You can lend your savings to your friend for their wedding or keep them for your joint business planned in two years."},"options":[{"text":{"fr":"Préserver le projet futur et refuser le prêt.","en":"Protect the future project and refuse the loan."},"weights":{"future":3}},{"text":{"fr":"Financer ce moment unique malgré le projet compromis.","en":"Fund this unique moment despite jeopardising the project."},"weights":{"future":-3}}]}'::jsonb),
('pack-friendship-18', 'friendship', 'future', '{"id":"pack-friendship-18","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton meilleur ami n’a qu’un mois de libre pour voyager avec toi. Accepter fait perdre une formation rare qui changerait ta carrière.","en":"Your best friend has just one month free to travel with you. Going means losing a rare course that could change your career."},"options":[{"text":{"fr":"Suivre la formation et renoncer au voyage ensemble.","en":"Take the course and give up the trip together."},"weights":{"future":3}},{"text":{"fr":"Partir avec lui et laisser passer la formation.","en":"Travel with them and let the course go."},"weights":{"future":-3}}]}'::jsonb),
('pack-friendship-19', 'friendship', 'future', '{"id":"pack-friendship-19","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Pour sauver votre amitié à long terme, un médiateur recommande six mois sans contact. Ton ami traverse justement une période de grande solitude.","en":"To save your friendship long-term, a mediator recommends six months without contact. Your friend is currently deeply lonely."},"options":[{"text":{"fr":"Respecter la distance pour reconstruire plus tard.","en":"Respect the distance to rebuild the friendship later."},"weights":{"future":3}},{"text":{"fr":"Rester présent maintenant malgré le risque pour la suite.","en":"Stay present now despite the risk to the friendship later."},"weights":{"future":-3}}]}'::jsonb),
('pack-friendship-20', 'friendship', 'future', '{"id":"pack-friendship-20","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu peux vendre aujourd’hui votre collection commune pour payer une fête mémorable, ou la conserver pour financer vos projets dans dix ans.","en":"You can sell your shared collection now to fund a memorable celebration, or keep it to finance your plans in ten years."},"options":[{"text":{"fr":"Garder la collection pour les projets futurs.","en":"Keep the collection for your future plans."},"weights":{"future":3}},{"text":{"fr":"La vendre pour créer ce souvenir maintenant.","en":"Sell it to make that memory together now."},"weights":{"future":-3}}]}'::jsonb),
('pack-friendship-21', 'friendship', 'structure', '{"id":"pack-friendship-21","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami te demande de lui donner les réponses d’un concours. Tu peux le sauver de l’échec, mais les autres candidats n’auront pas cette aide.","en":"Your friend asks for answers to an entrance test. You can spare them failure, but other candidates will not receive that help."},"options":[{"text":{"fr":"Respecter les règles et refuser de tricher.","en":"Follow the rules and refuse to help them cheat."},"weights":{"structure":3}},{"text":{"fr":"Contourner les règles pour aider mon ami.","en":"Break the rules to help my friend succeed."},"weights":{"structure":-3}}]}'::jsonb),
('pack-friendship-22', 'friendship', 'structure', '{"id":"pack-friendship-22","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Votre groupe a promis de ne jamais exclure quelqu’un d’un voyage. Un ami rend désormais chaque sortie pénible, sans avoir enfreint d’autre règle.","en":"Your group promised never to exclude anyone from a trip. One friend now makes every outing miserable without breaking any other rule."},"options":[{"text":{"fr":"Honorer notre règle et continuer à l’inviter.","en":"Honour our rule and keep inviting them."},"weights":{"structure":3}},{"text":{"fr":"Changer la règle et partir sans lui.","en":"Change the rule and travel without them."},"weights":{"structure":-3}}]}'::jsonb),
('pack-friendship-23', 'friendship', 'structure', '{"id":"pack-friendship-23","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu organises un concours et ton ami a envoyé son dossier dix minutes après la limite. Il était à l’hôpital ; accepter son dossier oblige à faire une exception.","en":"You run a competition and your friend applied ten minutes late. They were in hospital; accepting the application requires an exception."},"options":[{"text":{"fr":"Appliquer la même limite à tous, malgré sa situation.","en":"Apply the same deadline to everyone despite their situation."},"weights":{"structure":3}},{"text":{"fr":"Accepter son dossier en faisant une exception.","en":"Accept the application by making an exception."},"weights":{"structure":-3}}]}'::jsonb),
('pack-friendship-24', 'friendship', 'structure', '{"id":"pack-friendship-24","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu as promis de garder un secret qui ne met personne en danger. Le révéler réconcilierait deux amis brouillés depuis dix ans.","en":"You promised to keep a secret that puts nobody in danger. Revealing it would reconcile two friends estranged for ten years."},"options":[{"text":{"fr":"Garder ma parole et laisser le conflit durer.","en":"Keep my word and let the conflict continue."},"weights":{"structure":3}},{"text":{"fr":"Briser ma promesse pour les réconcilier.","en":"Break my promise to bring them back together."},"weights":{"structure":-3}}]}'::jsonb),
('pack-friendship-25', 'friendship', 'structure', '{"id":"pack-friendship-25","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Le règlement de votre club interdit les animaux. Ton ami ne peut venir qu’avec son vieux chien ; laisser entrer le chien risque de vous faire exclure tous les deux.","en":"Your club bans animals. Your friend can only attend with their elderly dog; letting it in risks both of you being excluded."},"options":[{"text":{"fr":"Respecter le règlement et renoncer à sa présence.","en":"Respect the rule and accept their absence."},"weights":{"structure":3}},{"text":{"fr":"Faire entrer le chien malgré le règlement.","en":"Let the dog in despite the club''s rule."},"weights":{"structure":-3}}]}'::jsonb),
('pack-friendship-26', 'friendship', 'ambition', '{"id":"pack-friendship-26","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous avez créé un projet à deux, mais une récompense ne peut porter qu’un nom. Ton ami a besoin de reconnaissance autant que toi.","en":"You built a project together, but an award can carry only one name. Your friend needs recognition as much as you do."},"options":[{"text":{"fr":"Défendre ma candidature, même contre mon ami.","en":"Argue for my own nomination, even against my friend."},"weights":{"ambition":3}},{"text":{"fr":"Laisser mon ami recevoir seul la récompense.","en":"Let my friend receive the award alone."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-friendship-27', 'friendship', 'ambition', '{"id":"pack-friendship-27","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami et toi visez le même emploi unique. Tu peux révéler une faiblesse réelle de son dossier pour augmenter tes chances.","en":"You and your friend want the same single job. You can reveal a genuine weakness in their application to improve your chances."},"options":[{"text":{"fr":"Mettre cette faiblesse en avant pour gagner le poste.","en":"Highlight that weakness to win the position."},"weights":{"ambition":3}},{"text":{"fr":"Me taire, même si cela lui donne l’avantage.","en":"Stay silent even if it gives them the advantage."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-friendship-28', 'friendship', 'ambition', '{"id":"pack-friendship-28","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu peux devenir célèbre en racontant une aventure vécue avec ton ami. Il accepte, mais seulement s’il reste anonyme et ne reçoit aucune reconnaissance.","en":"You could become famous by telling a story you shared with your friend. They agree, but only if they stay anonymous and receive no recognition."},"options":[{"text":{"fr":"Publier et assumer d’en recevoir seul la reconnaissance.","en":"Publish and accept receiving all the recognition."},"weights":{"ambition":3}},{"text":{"fr":"Renoncer à la célébrité pour ne pas effacer sa place.","en":"Give up fame rather than erase their part."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-friendship-29', 'friendship', 'ambition', '{"id":"pack-friendship-29","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Dans votre équipe, diriger te permettrait de réaliser ta vision. Ton ami veut ce rôle aussi ; vous savez que le perdant quittera le projet.","en":"Leading your team would let you realise your vision. Your friend wants the role too; you both know the loser will leave the project."},"options":[{"text":{"fr":"Me battre pour diriger malgré son départ possible.","en":"Fight to lead despite the possibility of them leaving."},"weights":{"ambition":3}},{"text":{"fr":"Lui laisser la direction pour rester à ses côtés.","en":"Let them lead so I can stay by their side."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-friendship-30', 'friendship', 'ambition', '{"id":"pack-friendship-30","pack":"friendship","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton ami te propose un travail utile mais anonyme. Au même moment, un projet moins utile te promet une forte reconnaissance publique.","en":"Your friend offers useful but anonymous work. Meanwhile, a less useful project promises you substantial public recognition."},"options":[{"text":{"fr":"Choisir le projet qui me donnera de la visibilité.","en":"Choose the project that will give me visibility."},"weights":{"ambition":3}},{"text":{"fr":"Travailler dans l’ombre sur le projet de mon ami.","en":"Work behind the scenes on my friend''s project."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-couple-01', 'couple', 'adventure', '{"id":"pack-couple-01","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Pour un million d’euros à partager, accepterais-tu que ton partenaire vive un an une relation amoureuse avec une autre personne ? Vous consentez tous les deux, mais rien ne garantit votre retour ensemble.","en":"For one million euros to share, would you agree to your partner spending a year in a romantic relationship with someone else? Both of you consent, but there is no guarantee you reunite."},"options":[{"text":{"fr":"Accepter l’argent et le risque de perdre notre couple.","en":"Accept the money and the risk of losing our relationship."},"weights":{"adventure":3}},{"text":{"fr":"Refuser le million pour préserver notre relation actuelle.","en":"Refuse the million to protect our current relationship."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-couple-02', 'couple', 'adventure', '{"id":"pack-couple-02","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire veut vendre votre logement pour ouvrir une maison d’hôtes à l’étranger. C’est son rêve, mais vous pourriez perdre toutes vos économies.","en":"Your partner wants to sell your home to open a guesthouse abroad. It is their dream, but you could lose all your savings."},"options":[{"text":{"fr":"Tenter l’aventure ensemble malgré le risque financier.","en":"Take the leap together despite the financial risk."},"weights":{"adventure":3}},{"text":{"fr":"Garder notre sécurité et lui demander de renoncer.","en":"Keep our security and ask them to give it up."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-couple-03', 'couple', 'adventure', '{"id":"pack-couple-03","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Votre couple s’essouffle. Une année de voyage pourrait vous rapprocher, mais elle exige de quitter vos deux emplois sans garantie au retour.","en":"Your relationship is losing momentum. A year of travel might bring you closer, but requires leaving both jobs with no guarantee on return."},"options":[{"text":{"fr":"Partir pour donner cette chance à notre couple.","en":"Leave to give our relationship that chance."},"weights":{"adventure":3}},{"text":{"fr":"Garder nos emplois malgré le risque de nous éloigner.","en":"Keep our jobs despite the risk of growing apart."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-couple-04', 'couple', 'adventure', '{"id":"pack-couple-04","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire te propose de vivre six mois dans une communauté isolée sans confort moderne. C’est important pour lui, mais tu ignores si tu le supporterais.","en":"Your partner proposes six months in a remote community without modern comforts. It matters to them, but you do not know whether you could handle it."},"options":[{"text":{"fr":"Essayer ensemble malgré cette grande incertitude.","en":"Try it together despite the considerable uncertainty."},"weights":{"adventure":3}},{"text":{"fr":"Refuser et le laisser vivre cette expérience sans moi.","en":"Refuse and let them have that experience without me."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-couple-05', 'couple', 'adventure', '{"id":"pack-couple-05","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Une occasion unique permet de déménager ensemble demain. Tu dois décider avant de visiter le lieu ; refuser signifie deux ans de relation à distance.","en":"A unique opportunity lets you move together tomorrow. You must decide without seeing the place; refusing means two years of long-distance love."},"options":[{"text":{"fr":"Déménager sans garanties pour rester ensemble.","en":"Move without guarantees to stay together."},"weights":{"adventure":3}},{"text":{"fr":"Choisir la distance plutôt que ce saut dans l’inconnu.","en":"Choose distance rather than this leap into the unknown."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-couple-06', 'couple', 'reason', '{"id":"pack-couple-06","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire a commis une faute au travail et un collègue innocent va être licencié. Dire la vérité sauve le collègue, mais fait perdre son poste à ton partenaire.","en":"Your partner made a mistake at work and an innocent colleague will be fired. Telling the truth saves the colleague but costs your partner their job."},"options":[{"text":{"fr":"Révéler la vérité malgré la perte de son emploi.","en":"Reveal the truth despite my partner losing their job."},"weights":{"reason":3}},{"text":{"fr":"Protéger mon partenaire en laissant accuser le collègue.","en":"Protect my partner and let the colleague take the blame."},"weights":{"reason":-3}}]}'::jsonb),
('pack-couple-07', 'couple', 'reason', '{"id":"pack-couple-07","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous devez choisir qui abandonne son emploi pour suivre l’autre. Ton partenaire gagne moins, mais adore son métier ; ton revenu assure votre logement.","en":"One of you must leave your job to follow the other. Your partner earns less but loves their work; your income pays for your home."},"options":[{"text":{"fr":"Privilégier le revenu qui sécurise notre situation.","en":"Prioritise the income that keeps us financially secure."},"weights":{"reason":3}},{"text":{"fr":"Préserver son métier passion, malgré la perte de revenus.","en":"Protect their beloved career despite losing income."},"weights":{"reason":-3}}]}'::jsonb),
('pack-couple-08', 'couple', 'reason', '{"id":"pack-couple-08","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire souhaite garder une maison héritée, pleine de souvenirs. La vendre réglerait vos dettes ; la garder impose dix ans de privations.","en":"Your partner wants to keep an inherited home full of memories. Selling it clears your debts; keeping it means ten years of sacrifices."},"options":[{"text":{"fr":"Vendre la maison pour sortir de l’endettement.","en":"Sell the house to get out of debt."},"weights":{"reason":3}},{"text":{"fr":"Préserver ses souvenirs et accepter les privations.","en":"Preserve those memories and accept the sacrifices."},"weights":{"reason":-3}}]}'::jsonb),
('pack-couple-09', 'couple', 'reason', '{"id":"pack-couple-09","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire te demande si tu souhaites encore vous marier. Tu as de vrais doutes ; les exprimer annulerait probablement la cérémonie déjà payée.","en":"Your partner asks whether you still want to marry. You have real doubts; voicing them would probably cancel the already-paid wedding."},"options":[{"text":{"fr":"Exprimer mes doutes malgré la cérémonie compromise.","en":"Voice my doubts despite jeopardising the ceremony."},"weights":{"reason":3}},{"text":{"fr":"Le rassurer pour protéger ce moment et ses sentiments.","en":"Reassure them to protect this moment and their feelings."},"weights":{"reason":-3}}]}'::jsonb),
('pack-couple-10', 'couple', 'reason', '{"id":"pack-couple-10","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Votre chien âgé a besoin d’un traitement très cher aux chances de succès faibles. Ton partenaire veut utiliser l’argent réservé à votre déménagement indispensable.","en":"Your elderly dog needs costly treatment with low odds of success. Your partner wants to use money saved for an essential move."},"options":[{"text":{"fr":"Préserver le budget du déménagement malgré son chagrin.","en":"Preserve the moving budget despite their grief."},"weights":{"reason":3}},{"text":{"fr":"Financer le traitement et compromettre notre déménagement.","en":"Fund the treatment and jeopardise our move."},"weights":{"reason":-3}}]}'::jsonb),
('pack-couple-11', 'couple', 'independence', '{"id":"pack-couple-11","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire ne supporte plus ton amitié avec ton ex, pourtant sans ambiguïté. Il te demande d’y mettre fin pour continuer votre couple.","en":"Your partner cannot accept your friendship with your ex, despite no romantic ambiguity. They ask you to end it for your relationship to continue."},"options":[{"text":{"fr":"Garder mon amitié, quitte à perdre mon couple.","en":"Keep my friendship, even if I lose my relationship."},"weights":{"independence":3}},{"text":{"fr":"Couper ce lien pour préserver notre couple.","en":"Cut that bond to preserve our relationship."},"weights":{"independence":-3}}]}'::jsonb),
('pack-couple-12', 'couple', 'independence', '{"id":"pack-couple-12","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire veut accéder à tous tes messages pour retrouver confiance. Tu n’as rien à cacher, mais cela supprimerait toute intimité personnelle.","en":"Your partner wants access to all your messages to rebuild trust. You have nothing to hide, but it would remove all personal privacy."},"options":[{"text":{"fr":"Refuser cet accès même si cela menace notre couple.","en":"Refuse that access even if it threatens our relationship."},"weights":{"independence":3}},{"text":{"fr":"Partager mes messages pour le rassurer.","en":"Share my messages to reassure my partner."},"weights":{"independence":-3}}]}'::jsonb),
('pack-couple-13', 'couple', 'independence', '{"id":"pack-couple-13","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu rêves d’un voyage seul depuis dix ans. Ton partenaire le vivrait comme un abandon et te demande de renoncer pour rester ensemble cet été.","en":"You have dreamed of travelling alone for ten years. Your partner would feel abandoned and asks you to stay together this summer instead."},"options":[{"text":{"fr":"Partir seul et assumer sa déception.","en":"Travel alone and accept their disappointment."},"weights":{"independence":3}},{"text":{"fr":"Renoncer au voyage pour préserver notre complicité.","en":"Give up the trip to preserve our closeness."},"weights":{"independence":-3}}]}'::jsonb),
('pack-couple-14', 'couple', 'independence', '{"id":"pack-couple-14","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire veut mettre tous vos revenus sur un compte commun. Tu aides discrètement un proche ; accepter te ferait perdre la liberté de décider seul de cette aide.","en":"Your partner wants all income in a shared account. You privately support a relative; agreeing means losing sole control over that help."},"options":[{"text":{"fr":"Garder une part d’argent indépendante malgré le conflit.","en":"Keep some money separate despite the conflict."},"weights":{"independence":3}},{"text":{"fr":"Tout mettre en commun et décider désormais à deux.","en":"Pool everything and make those decisions together."},"weights":{"independence":-3}}]}'::jsonb),
('pack-couple-15', 'couple', 'independence', '{"id":"pack-couple-15","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Une passion occupe tes week-ends. Ton partenaire demande que tu l’abandonnes pour avoir davantage de temps commun ; aucun compromis ne lui convient.","en":"A passion takes up your weekends. Your partner asks you to abandon it for more time together; no compromise works for them."},"options":[{"text":{"fr":"Conserver ma passion malgré une séparation possible.","en":"Keep my passion despite a possible separation."},"weights":{"independence":3}},{"text":{"fr":"Y renoncer pour privilégier notre vie commune.","en":"Give it up to prioritise our shared life."},"weights":{"independence":-3}}]}'::jsonb),
('pack-couple-16', 'couple', 'future', '{"id":"pack-couple-16","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire peut enfin partir avec toi pour un mois. Cela exige de dépenser l’apport prévu pour votre premier logement.","en":"Your partner can finally take a month away with you. It requires spending the deposit saved for your first home."},"options":[{"text":{"fr":"Garder l’apport et reporter ce voyage rare.","en":"Keep the deposit and postpone this rare trip."},"weights":{"future":3}},{"text":{"fr":"Partir maintenant et retarder notre achat immobilier.","en":"Travel now and delay buying our home."},"weights":{"future":-3}}]}'::jsonb),
('pack-couple-17', 'couple', 'future', '{"id":"pack-couple-17","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un contrat de trois ans à l’étranger sécuriserait votre avenir financier. Ton partenaire ne peut pas suivre et redoute que la distance vous sépare.","en":"A three-year contract abroad would secure your financial future. Your partner cannot follow and fears the distance will break you apart."},"options":[{"text":{"fr":"Accepter le contrat pour construire notre avenir.","en":"Accept the contract to build our future."},"weights":{"future":3}},{"text":{"fr":"Rester ensemble et renoncer à cette sécurité future.","en":"Stay together and give up that future security."},"weights":{"future":-3}}]}'::jsonb),
('pack-couple-18', 'couple', 'future', '{"id":"pack-couple-18","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous avez économisé pour une fête de mariage unique. Utiliser cet argent pour une formation permettrait à ton partenaire de quitter un métier pénible dans deux ans.","en":"You saved for a unique wedding celebration. Using that money for training would let your partner leave a difficult job in two years."},"options":[{"text":{"fr":"Financer la formation et renoncer à la grande fête.","en":"Fund the training and give up the big celebration."},"weights":{"future":3}},{"text":{"fr":"Vivre la fête rêvée et reporter la reconversion.","en":"Have the dream celebration and delay the career change."},"weights":{"future":-3}}]}'::jsonb),
('pack-couple-19', 'couple', 'future', '{"id":"pack-couple-19","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire veut réduire son travail pour profiter de vos jeunes années. Cela vous empêcherait durablement de mettre de l’argent de côté.","en":"Your partner wants to work less to enjoy your younger years together. It would prevent you saving money for the foreseeable future."},"options":[{"text":{"fr":"Continuer à épargner même avec moins de temps ensemble.","en":"Keep saving even with less time together."},"weights":{"future":3}},{"text":{"fr":"Privilégier notre temps commun et accepter l’incertitude.","en":"Prioritise our time together and accept uncertainty."},"weights":{"future":-3}}]}'::jsonb),
('pack-couple-20', 'couple', 'future', '{"id":"pack-couple-20","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Une thérapie de couple vous demande d’annuler vos vacances pour financer plusieurs mois de séances. Ton partenaire espérait ce voyage pour retrouver de la joie.","en":"Couples therapy requires cancelling your holiday to fund months of sessions. Your partner hoped the trip would bring back some joy."},"options":[{"text":{"fr":"Investir dans les séances pour reconstruire la relation.","en":"Invest in therapy to rebuild the relationship."},"weights":{"future":3}},{"text":{"fr":"Choisir les vacances pour nous retrouver maintenant.","en":"Choose the holiday to reconnect right now."},"weights":{"future":-3}}]}'::jsonb),
('pack-couple-21', 'couple', 'structure', '{"id":"pack-couple-21","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous aviez promis de rester exclusifs. Ton partenaire te propose aujourd’hui une relation ouverte, librement consentie ; refuser pourrait mener à une séparation.","en":"You promised exclusivity. Your partner now proposes a mutually consensual open relationship; refusing could lead to separation."},"options":[{"text":{"fr":"Maintenir notre accord initial, quitte à nous séparer.","en":"Keep our original agreement even if we separate."},"weights":{"structure":3}},{"text":{"fr":"Redéfinir notre accord pour essayer de rester ensemble.","en":"Redefine our agreement to try to stay together."},"weights":{"structure":-3}}]}'::jsonb),
('pack-couple-22', 'couple', 'structure', '{"id":"pack-couple-22","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous partagez toujours les dépenses à égalité. Ton partenaire traverse une période difficile et demande une exception durable qui te ferait payer davantage.","en":"You always split costs equally. Your partner is struggling and asks for a lasting exception that would make you pay more."},"options":[{"text":{"fr":"Maintenir la règle convenue malgré les tensions.","en":"Keep the agreed rule despite the tension."},"weights":{"structure":3}},{"text":{"fr":"Adapter notre règle pour tenir compte de sa situation.","en":"Adapt our rule to account for their situation."},"weights":{"structure":-3}}]}'::jsonb),
('pack-couple-23', 'couple', 'structure', '{"id":"pack-couple-23","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous aviez convenu de ne jamais emprunter à vos familles. Une aide familiale permettrait aujourd’hui de sauver votre logement, mais créerait une dette affective.","en":"You agreed never to borrow from family. Family help could now save your home, but would create an emotional debt."},"options":[{"text":{"fr":"Respecter notre accord malgré la perte du logement.","en":"Honour our agreement despite losing the home."},"weights":{"structure":3}},{"text":{"fr":"Faire une exception pour conserver notre logement.","en":"Make an exception to keep our home."},"weights":{"structure":-3}}]}'::jsonb),
('pack-couple-24', 'couple', 'structure', '{"id":"pack-couple-24","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire souhaite annuler au dernier moment un engagement pris auprès d’amis pour passer un anniversaire imprévu avec toi.","en":"Your partner wants to cancel a commitment to friends at the last minute to spend an unexpected anniversary celebration with you."},"options":[{"text":{"fr":"Tenir notre engagement malgré l’occasion manquée.","en":"Keep our commitment despite missing the occasion."},"weights":{"structure":3}},{"text":{"fr":"Changer nos plans pour privilégier ce moment à deux.","en":"Change our plans to prioritise this moment together."},"weights":{"structure":-3}}]}'::jsonb),
('pack-couple-25', 'couple', 'structure', '{"id":"pack-couple-25","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous avez fixé une règle : pas de téléphone à table. Ton partenaire veut une exception quotidienne pour un groupe de soutien important pour lui.","en":"You set a rule: no phones at the table. Your partner wants a daily exception for a support group that matters to them."},"options":[{"text":{"fr":"Garder la règle pour protéger notre rituel commun.","en":"Keep the rule to protect our shared ritual."},"weights":{"structure":3}},{"text":{"fr":"Assouplir le rituel pour répondre à son besoin.","en":"Relax the ritual to accommodate their need."},"weights":{"structure":-3}}]}'::jsonb),
('pack-couple-26', 'couple', 'ambition', '{"id":"pack-couple-26","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire et toi êtes finalistes pour le même poste. Tu peux gagner en montrant clairement pourquoi ton dossier est meilleur, mais il vivrait cela comme une trahison.","en":"You and your partner are finalists for the same job. You can win by showing why your application is better, but they would feel betrayed."},"options":[{"text":{"fr":"Défendre ma candidature jusqu’au bout malgré le conflit.","en":"Defend my application to the end despite the conflict."},"weights":{"ambition":3}},{"text":{"fr":"Me retirer pour lui laisser cette chance.","en":"Withdraw to give my partner that chance."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-couple-27', 'couple', 'ambition', '{"id":"pack-couple-27","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous avez créé une entreprise ensemble. Un investisseur exige que tu deviennes le seul visage public ; ton partenaire resterait dans l’ombre.","en":"You founded a business together. An investor insists you become its only public face; your partner would remain behind the scenes."},"options":[{"text":{"fr":"Accepter le rôle public malgré le déséquilibre.","en":"Accept the public role despite the imbalance."},"weights":{"ambition":3}},{"text":{"fr":"Refuser l’investissement pour préserver notre égalité.","en":"Refuse the investment to preserve equal recognition."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-couple-28', 'couple', 'ambition', '{"id":"pack-couple-28","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Une émission veut raconter votre réussite, mais uniquement à travers toi. Ton partenaire accepte de ne pas être crédité ; tu sais combien il a contribué.","en":"A show wants to tell your success story, but only through you. Your partner accepts receiving no credit; you know how much they contributed."},"options":[{"text":{"fr":"Accepter cette visibilité personnelle avec son accord.","en":"Accept the personal visibility with their agreement."},"weights":{"ambition":3}},{"text":{"fr":"Refuser cette visibilité qui effacerait sa contribution.","en":"Refuse visibility that would erase their contribution."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-couple-29', 'couple', 'ambition', '{"id":"pack-couple-29","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu peux devenir responsable d’un projet où ton partenaire travaille aussi. Il devra accepter ton autorité ou quitter l’équipe.","en":"You can lead a project your partner also works on. They will have to accept your authority or leave the team."},"options":[{"text":{"fr":"Prendre la direction et assumer cette tension.","en":"Take the leadership role and accept the tension."},"weights":{"ambition":3}},{"text":{"fr":"Renoncer au poste pour éviter ce rapport de pouvoir.","en":"Give up the role to avoid that power imbalance."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-couple-30', 'couple', 'ambition', '{"id":"pack-couple-30","pack":"couple","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton partenaire te propose de soutenir discrètement son rêve pendant deux ans. Pendant ce temps, une occasion de reconnaissance importante pour toi disparaîtra.","en":"Your partner asks you to quietly support their dream for two years. Meanwhile, an important chance for your own recognition will disappear."},"options":[{"text":{"fr":"Saisir mon occasion même si son rêve doit attendre.","en":"Take my chance even if their dream must wait."},"weights":{"ambition":3}},{"text":{"fr":"Soutenir son rêve et laisser passer ma reconnaissance.","en":"Support their dream and let my recognition pass."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-family-01', 'family', 'adventure', '{"id":"pack-family-01","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ta famille te propose d’engager ton épargne pour sauver son restaurant. La réussite est incertaine ; refuser signifie sa fermeture.","en":"Your family asks you to invest your savings to save their restaurant. Success is uncertain; refusing means it closes."},"options":[{"text":{"fr":"Risquer mon épargne pour sauver le restaurant.","en":"Risk my savings to save the restaurant."},"weights":{"adventure":3}},{"text":{"fr":"Protéger mon épargne et accepter sa fermeture.","en":"Protect my savings and accept its closure."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-family-02', 'family', 'adventure', '{"id":"pack-family-02","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton frère veut traverser le pays à pied après une année difficile. Il te demande de l’accompagner, mais tu devrais abandonner un contrat stable.","en":"After a difficult year, your brother wants to walk across the country. He asks you to join, but you would have to give up stable work."},"options":[{"text":{"fr":"Partir avec lui malgré l’incertitude professionnelle.","en":"Go with him despite the career uncertainty."},"weights":{"adventure":3}},{"text":{"fr":"Garder mon contrat et le laisser partir seul.","en":"Keep my contract and let him go alone."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-family-03', 'family', 'adventure', '{"id":"pack-family-03","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un parent veut enfin réaliser un voyage exigeant. Tu peux l’accompagner, mais cela épuiserait votre réserve d’urgence sans garantie que le voyage se passe bien.","en":"A parent finally wants to take a demanding trip. You can join them, but it would exhaust your emergency fund with no guarantee it goes well."},"options":[{"text":{"fr":"Tenter ce voyage ensemble malgré les risques.","en":"Take the trip together despite the risks."},"weights":{"adventure":3}},{"text":{"fr":"Préserver notre réserve et renoncer à ce rêve.","en":"Keep our emergency fund and give up this dream."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-family-04', 'family', 'adventure', '{"id":"pack-family-04","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ta sœur te propose de quitter la ville pour vivre ensemble d’une ferme. Vous n’avez aucune expérience ; rester lui fait abandonner son projet.","en":"Your sister proposes leaving the city to run a farm together. Neither of you has experience; staying makes her abandon the plan."},"options":[{"text":{"fr":"Essayer cette nouvelle vie avec elle.","en":"Try this new way of life with her."},"weights":{"adventure":3}},{"text":{"fr":"Garder ma stabilité malgré son projet abandonné.","en":"Keep my stability despite her abandoned project."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-family-05', 'family', 'adventure', '{"id":"pack-family-05","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Révéler publiquement un abus dans l’entreprise familiale pourrait sauver des emplois ailleurs, mais menace votre revenu et vos liens familiaux.","en":"Publicly exposing wrongdoing in the family business could save jobs elsewhere, but threatens your income and family bonds."},"options":[{"text":{"fr":"Prendre le risque de parler publiquement.","en":"Take the risk of speaking publicly."},"weights":{"adventure":3}},{"text":{"fr":"Préserver notre sécurité et ne pas prendre la parole.","en":"Preserve our security and decline to speak out."},"weights":{"adventure":-3}}]}'::jsonb),
('pack-family-06', 'family', 'reason', '{"id":"pack-family-06","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un parent t’a confié la distribution d’une aide familiale. Ton frère réclame la plus grosse part, mais une cousine inconnue de toi en a davantage besoin.","en":"A parent put you in charge of distributing family aid. Your brother wants most of it, but a cousin you barely know needs it more."},"options":[{"text":{"fr":"Donner selon les besoins, même contre mon frère.","en":"Allocate by need, even against my brother''s wishes."},"weights":{"reason":3}},{"text":{"fr":"Favoriser mon frère malgré les besoins de ma cousine.","en":"Favour my brother despite my cousin''s greater need."},"weights":{"reason":-3}}]}'::jsonb),
('pack-family-07', 'family', 'reason', '{"id":"pack-family-07","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton enfant adulte a causé des dégâts et accuse quelqu’un d’autre. Dire la vérité lui coûterait une grosse somme qu’il ne peut pas payer.","en":"Your adult child caused damage and blames someone else. Telling the truth would cost them a large sum they cannot afford."},"options":[{"text":{"fr":"Rétablir la vérité malgré les conséquences pour lui.","en":"Set the record straight despite the consequences for them."},"weights":{"reason":3}},{"text":{"fr":"Le protéger en laissant l’autre supporter les dégâts.","en":"Protect them and let the other person bear the cost."},"weights":{"reason":-3}}]}'::jsonb),
('pack-family-08', 'family', 'reason', '{"id":"pack-family-08","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"La maison familiale est trop chère à entretenir. La vendre réglerait les difficultés de tous, mais ton parent y a vécu toute sa vie et refuse de partir.","en":"The family home is too expensive to maintain. Selling would solve everyone''s financial problems, but your parent has lived there all their life and refuses to leave."},"options":[{"text":{"fr":"Soutenir la vente malgré sa peine.","en":"Support selling despite my parent''s distress."},"weights":{"reason":3}},{"text":{"fr":"Préserver la maison et accepter les sacrifices financiers.","en":"Keep the house and accept the financial sacrifices."},"weights":{"reason":-3}}]}'::jsonb),
('pack-family-09', 'family', 'reason', '{"id":"pack-family-09","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ta sœur veut lancer une activité que tu crois vouée à l’échec. Elle te demande ton avis juste avant de démissionner et prendrait tes doutes comme un manque de soutien.","en":"Your sister wants to start a business you think will fail. She asks your opinion before resigning and would see your doubts as a lack of support."},"options":[{"text":{"fr":"Exprimer franchement mes doutes malgré sa réaction.","en":"State my doubts honestly despite her reaction."},"weights":{"reason":3}},{"text":{"fr":"L’encourager pour préserver sa confiance en elle.","en":"Encourage her to protect her self-confidence."},"weights":{"reason":-3}}]}'::jsonb),
('pack-family-10', 'family', 'reason', '{"id":"pack-family-10","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un héritage peut payer les études d’un neveu brillant ou les dettes répétées de ton frère. Ton frère te supplie de le choisir une dernière fois.","en":"An inheritance can fund a talented nephew''s education or your brother''s recurring debts. Your brother begs you to choose him one last time."},"options":[{"text":{"fr":"Financer les études malgré la détresse de mon frère.","en":"Fund the education despite my brother''s distress."},"weights":{"reason":3}},{"text":{"fr":"Secourir mon frère et renoncer au financement des études.","en":"Help my brother and give up funding the education."},"weights":{"reason":-3}}]}'::jsonb),
('pack-family-11', 'family', 'independence', '{"id":"pack-family-11","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tes parents financeraient ton logement à condition de choisir eux-mêmes la ville et de pouvoir venir sans prévenir.","en":"Your parents would pay for your home if they choose the city and can visit without warning."},"options":[{"text":{"fr":"Refuser cette aide pour garder mon indépendance.","en":"Refuse the help to keep my independence."},"weights":{"independence":3}},{"text":{"fr":"Accepter ces conditions pour rester soutenu par eux.","en":"Accept the conditions to keep their support."},"weights":{"independence":-3}}]}'::jsonb),
('pack-family-12', 'family', 'independence', '{"id":"pack-family-12","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ta famille attend que tu reprennes son commerce. Tu rêves d’un autre métier ; refuser signifie vendre une entreprise transmise depuis trois générations.","en":"Your family expects you to take over the shop. You dream of another career; refusing means selling a business passed down for three generations."},"options":[{"text":{"fr":"Choisir mon métier malgré la fin de la transmission.","en":"Choose my career despite ending the family succession."},"weights":{"independence":3}},{"text":{"fr":"Reprendre le commerce et renoncer à mon projet.","en":"Take over the shop and give up my own plan."},"weights":{"independence":-3}}]}'::jsonb),
('pack-family-13', 'family', 'independence', '{"id":"pack-family-13","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un parent souhaite vivre chez toi durablement. Il a une autre solution correcte, mais vivrait ton refus comme un rejet ; tu perdrais ton intimité.","en":"A parent wants to live with you permanently. They have another decent option but would feel rejected if you refused; you would lose your privacy."},"options":[{"text":{"fr":"Préserver mon espace et accepter sa déception.","en":"Preserve my space and accept their disappointment."},"weights":{"independence":3}},{"text":{"fr":"L’accueillir pour préserver notre lien familial.","en":"Welcome them to preserve our family bond."},"weights":{"independence":-3}}]}'::jsonb),
('pack-family-14', 'family', 'independence', '{"id":"pack-family-14","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Toute ta famille exige ta présence chaque dimanche. C’est ton seul jour libre pour un projet personnel qui te tient à cœur.","en":"Your whole family expects you every Sunday. It is your only free day for a personal project that matters deeply to you."},"options":[{"text":{"fr":"Réserver mes dimanches à mon projet malgré les reproches.","en":"Keep Sundays for my project despite their criticism."},"weights":{"independence":3}},{"text":{"fr":"Rester présent chaque semaine et reporter mon projet.","en":"Attend every week and postpone my project."},"weights":{"independence":-3}}]}'::jsonb),
('pack-family-15', 'family', 'independence', '{"id":"pack-family-15","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ta famille veut que tu portes un nom choisi par tradition pour ton enfant. Ton partenaire et toi avez un autre choix ; résister provoquerait une longue rupture.","en":"Your family wants a traditional name for your child. You and your partner prefer another; resisting would cause a long family rift."},"options":[{"text":{"fr":"Garder notre choix malgré la rupture familiale.","en":"Keep our choice despite the family rift."},"weights":{"independence":3}},{"text":{"fr":"Accepter le nom familial pour préserver les liens.","en":"Accept the family name to preserve those bonds."},"weights":{"independence":-3}}]}'::jsonb),
('pack-family-16', 'family', 'future', '{"id":"pack-family-16","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un parent a encore une année pour faire le voyage dont il rêve. L’aider signifie utiliser l’argent réservé à ta formation de reconversion.","en":"A parent has one last year to take their dream trip. Helping means using the money saved for your career-change training."},"options":[{"text":{"fr":"Préserver ma formation et renoncer au voyage.","en":"Protect my training and give up the trip."},"weights":{"future":3}},{"text":{"fr":"Financer le voyage tant qu’il est encore possible.","en":"Fund the trip while it is still possible."},"weights":{"future":-3}}]}'::jsonb),
('pack-family-17', 'family', 'future', '{"id":"pack-family-17","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu peux travailler deux ans loin de tes enfants pour financer leurs études, ou rester avec eux sans pouvoir constituer cette épargne.","en":"You can work away from your children for two years to fund their education, or stay with them without building those savings."},"options":[{"text":{"fr":"Partir pour financer leurs futures études.","en":"Leave to fund their future education."},"weights":{"future":3}},{"text":{"fr":"Rester présent pendant ces deux années irremplaçables.","en":"Stay present for those two irreplaceable years."},"weights":{"future":-3}}]}'::jsonb),
('pack-family-18', 'family', 'future', '{"id":"pack-family-18","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton frère sort d’une période difficile et veut une fête pour repartir. Tu gardais cette somme pour un fonds familial d’urgence.","en":"Your brother is emerging from a difficult period and wants a celebration to start anew. You had saved that money for family emergencies."},"options":[{"text":{"fr":"Conserver le fonds pour les besoins futurs.","en":"Keep the fund for future needs."},"weights":{"future":3}},{"text":{"fr":"Payer la fête pour lui offrir ce nouveau départ.","en":"Pay for the celebration to give him that fresh start."},"weights":{"future":-3}}]}'::jsonb),
('pack-family-19', 'family', 'future', '{"id":"pack-family-19","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"La famille peut vendre aujourd’hui un terrain pour se retrouver tous une dernière fois, ou le conserver pour la sécurité financière des petits-enfants.","en":"Your family can sell land today to reunite everyone one last time, or keep it for the grandchildren''s financial security."},"options":[{"text":{"fr":"Conserver le terrain pour la génération suivante.","en":"Keep the land for the next generation."},"weights":{"future":3}},{"text":{"fr":"Le vendre pour vivre cette réunion maintenant.","en":"Sell it to make that reunion happen now."},"weights":{"future":-3}}]}'::jsonb),
('pack-family-20', 'family', 'future', '{"id":"pack-family-20","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Une promotion exige de manquer presque tous les week-ends familiaux pendant un an. Ensuite, tu pourrais réduire ton travail pendant cinq ans.","en":"A promotion requires missing almost every family weekend for a year. Afterwards, you could work less for five years."},"options":[{"text":{"fr":"Accepter cette année difficile pour gagner du temps ensuite.","en":"Accept the difficult year to gain time afterwards."},"weights":{"future":3}},{"text":{"fr":"Préserver les week-ends actuels et refuser la promotion.","en":"Protect our weekends now and refuse the promotion."},"weights":{"future":-3}}]}'::jsonb),
('pack-family-21', 'family', 'structure', '{"id":"pack-family-21","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un héritage doit être partagé à égalité selon une promesse. Un de tes frères est maintenant très riche, l’autre sans ressources.","en":"An inheritance must be split equally under a promise. One brother is now very wealthy; the other has nothing."},"options":[{"text":{"fr":"Tenir la promesse d’un partage égal.","en":"Honour the promise of an equal split."},"weights":{"structure":3}},{"text":{"fr":"Adapter le partage aux besoins actuels.","en":"Adapt the split to their current needs."},"weights":{"structure":-3}}]}'::jsonb),
('pack-family-22', 'family', 'structure', '{"id":"pack-family-22","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tes parents ont interdit à tous de lire leur journal après leur mort. Il pourrait répondre à une question qui déchire la famille depuis longtemps.","en":"Your parents forbade anyone from reading their diary after their death. It might answer a question that has long divided the family."},"options":[{"text":{"fr":"Respecter leur volonté malgré le mystère.","en":"Respect their wishes despite the mystery."},"weights":{"structure":3}},{"text":{"fr":"Lire le journal pour tenter d’apaiser la famille.","en":"Read the diary to try to bring the family peace."},"weights":{"structure":-3}}]}'::jsonb),
('pack-family-23', 'family', 'structure', '{"id":"pack-family-23","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Vous avez fixé une limite d’aide financière à chaque proche. Ta sœur la dépasse aujourd’hui pour une urgence réelle, mais tu as déjà refusé d’autres exceptions.","en":"You set a limit on financial help for each relative. Your sister exceeds it for a genuine emergency, but you have already refused other exceptions."},"options":[{"text":{"fr":"Appliquer la même limite malgré son urgence.","en":"Apply the same limit despite her emergency."},"weights":{"structure":3}},{"text":{"fr":"Faire une exception pour répondre à son besoin.","en":"Make an exception to meet her need."},"weights":{"structure":-3}}]}'::jsonb),
('pack-family-24', 'family', 'structure', '{"id":"pack-family-24","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Une tradition exige que l’aîné prononce l’hommage familial. Le plus jeune était beaucoup plus proche du défunt et demande de le remplacer.","en":"Tradition says the eldest gives the family tribute. The youngest was much closer to the deceased and asks to take their place."},"options":[{"text":{"fr":"Respecter la tradition malgré cette proximité différente.","en":"Respect tradition despite the difference in closeness."},"weights":{"structure":3}},{"text":{"fr":"Changer la tradition pour laisser parler le plus proche.","en":"Change tradition to let the closest person speak."},"weights":{"structure":-3}}]}'::jsonb),
('pack-family-25', 'family', 'structure', '{"id":"pack-family-25","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu as promis de ne jamais prêter la voiture familiale. Ton cousin en a besoin pour retrouver son enfant après une longue séparation ; aucune autre solution n’existe ce jour-là.","en":"You promised never to lend the family car. Your cousin needs it to see their child after a long separation; no other option exists that day."},"options":[{"text":{"fr":"Tenir ma promesse malgré ce rendez-vous manqué.","en":"Keep my promise despite the missed reunion."},"weights":{"structure":3}},{"text":{"fr":"Prêter la voiture en brisant ma promesse.","en":"Lend the car and break my promise."},"weights":{"structure":-3}}]}'::jsonb),
('pack-family-26', 'family', 'ambition', '{"id":"pack-family-26","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"L’entreprise familiale cherche un dirigeant. Tu sais pouvoir la faire grandir, mais ta sœur attend ce rôle depuis longtemps et partirait si tu le prends.","en":"The family business needs a leader. You know you could grow it, but your sister has long wanted the role and would leave if you take it."},"options":[{"text":{"fr":"Prendre la direction malgré son départ possible.","en":"Take the leadership role despite her possible departure."},"weights":{"ambition":3}},{"text":{"fr":"Lui laisser le rôle et renoncer à ma vision.","en":"Let her take the role and give up my vision."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-family-27', 'family', 'ambition', '{"id":"pack-family-27","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Un prix récompense le projet que tu as mené avec ton frère. Une seule personne peut être nommée ; vous y avez contribué autant l’un que l’autre.","en":"An award recognises the project you led with your brother. Only one person can be named; you contributed equally."},"options":[{"text":{"fr":"Défendre mon nom pour recevoir le prix.","en":"Argue for my name to receive the award."},"weights":{"ambition":3}},{"text":{"fr":"Laisser mon frère recevoir cette reconnaissance.","en":"Let my brother receive the recognition."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-family-28', 'family', 'ambition', '{"id":"pack-family-28","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Tu peux publier l’histoire de la réussite familiale sous ton nom. Tes proches consentent à rester anonymes, mais le public pensera que tu as tout construit seul.","en":"You can publish your family''s success story under your name. Your relatives agree to stay anonymous, but the public will think you built it alone."},"options":[{"text":{"fr":"Publier et accepter cette reconnaissance personnelle.","en":"Publish and accept that personal recognition."},"weights":{"ambition":3}},{"text":{"fr":"Renoncer à cette visibilité qui masque leur contribution.","en":"Give up visibility that hides their contribution."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-family-29', 'family', 'ambition', '{"id":"pack-family-29","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Une occasion de diriger une association importante arrive quand ta famille te demande une année d’aide discrète pour soutenir un proche.","en":"A chance to lead an important association arrives when your family asks for a year of quiet help supporting a relative."},"options":[{"text":{"fr":"Prendre la direction et laisser la famille s’organiser.","en":"Take the leadership role and let the family organise support."},"weights":{"ambition":3}},{"text":{"fr":"Aider dans l’ombre et laisser passer cette occasion.","en":"Help behind the scenes and let the opportunity pass."},"weights":{"ambition":-3}}]}'::jsonb),
('pack-family-30', 'family', 'ambition', '{"id":"pack-family-30","pack":"family","stableScoring":true,"theme":"relationships","prompt":{"fr":"Ton parent te propose de financer un projet à condition qu’il porte uniquement son nom. Sans cela, ton idée ne verra probablement jamais le jour.","en":"Your parent offers to fund a project only if it carries their name alone. Otherwise, your idea will probably never happen."},"options":[{"text":{"fr":"Refuser de disparaître derrière son nom.","en":"Refuse to disappear behind their name."},"weights":{"ambition":3}},{"text":{"fr":"Accepter de rester anonyme pour réaliser le projet.","en":"Accept anonymity to make the project happen."},"weights":{"ambition":-3}}]}'::jsonb)
